// components/EnhancedVideo.js
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Video } from 'expo-av';
import * as FileSystem from 'expo-file-system';

const EnhancedVideo = ({
  uri,
  poster,
  style,
  shouldPlay = false,
  shouldLoad = true,
  isLooping = true,
  isMuted = false,
  resizeMode = "cover",
}) => {
  const videoRef = useRef(null);
  const [videoLoaded, setVideoLoaded] = useState(false);
  const [cachedUri, setCachedUri] = useState(null);

  // Handle play/pause control
  const handlePlayControl = useCallback(async () => {
    if (!videoRef.current) return;
    
    try {
      if (shouldPlay) {
        await videoRef.current.playAsync();
      } else {
        await videoRef.current.pauseAsync();
      }
    } catch (error) {
      console.log('🎥 EnhancedVideo play control error:', error?.message || error);
    }
  }, [shouldPlay]);

  // Apply play/pause when shouldPlay changes
  useEffect(() => {
    handlePlayControl();
  }, [handlePlayControl]);

  // Cache video in background while streaming from original URI
  useEffect(() => {
    if (!shouldLoad || !uri) return;
    
    let isMounted = true;
    
    const cacheVideo = async () => {
      try {
        const fileName = encodeURIComponent(uri).replace(/[^a-zA-Z0-9]/g, '').substring(0, 48);
        const fileUri = `${FileSystem.cacheDirectory}vid-${fileName}.mp4`;
        
        const fileInfo = await FileSystem.getInfoAsync(fileUri);
        if (fileInfo.exists && isMounted) {
          setCachedUri(fileUri);
          return;
        }
        
        // Download in background
        const downloadResult = await FileSystem.downloadAsync(uri, fileUri);
        if (downloadResult.status === 200 && isMounted) {
          setCachedUri(fileUri);
        }
      } catch (error) {
        console.log('🎥 Background caching failed:', error?.message || error);
      }
    };
    
    cacheVideo();
    
    return () => {
      isMounted = false;
    };
  }, [uri, shouldLoad]);

  // Handle video ready state
  const onReadyForDisplay = useCallback(() => {
    setTimeout(() => {
      setVideoLoaded(true);
      // Give a little nudge if shouldPlay is true
      if (shouldPlay && videoRef.current) {
        videoRef.current.playAsync().catch(() => {});
      }
    }, 300);
  }, [shouldPlay]);

  if (!shouldLoad || !uri) {
    return null;
  }

  return (
    <Video
      ref={videoRef}
      source={{ uri: cachedUri || uri }}
      posterSource={poster && typeof poster === 'string' ? { uri: poster } : undefined}
      usePoster={!!(poster && typeof poster === 'string')}
      style={[style, { opacity: videoLoaded || !poster ? 1 : 0 }]}
      shouldPlay={shouldPlay}
      isMuted={isMuted}
      isLooping={isLooping}
      resizeMode={resizeMode}
      onReadyForDisplay={onReadyForDisplay}
      onError={(error) => {
        console.log('🎥 Video playback error:', error);
      }}
    />
  );
};

export default EnhancedVideo;
